//! Joins the per-area table files under `src/ids/` and `src/groups/` into
//! the `diag_id_table!` and `diag_group_table!` macros (spec/diag.md §2.4).
//!
//! Each macro passes every row of its files, in file-name order, followed by
//! the rows it is invoked with (the legacy tail block), to `diag_ids!` or
//! `diag_groups!`. Comment and blank lines are left out; nothing else is
//! interpreted here, so a malformed row is reported by the compiler against
//! the generated file, after a `// src/<dir>/<file>` line naming its source.
#![forbid(unsafe_code)]

use std::path::{Path, PathBuf};
use std::{env, fs};

fn main() {
    println!("cargo:rerun-if-changed=build.rs");
    let manifest = PathBuf::from(env::var_os("CARGO_MANIFEST_DIR").expect("CARGO_MANIFEST_DIR"));
    let out = PathBuf::from(env::var_os("OUT_DIR").expect("OUT_DIR"));
    generate(&manifest, &out, "ids", "diag_id_table", "diag_ids");
    generate(&manifest, &out, "groups", "diag_group_table", "diag_groups");
}

fn generate(manifest: &Path, out: &Path, dir: &str, table: &str, inner: &str) {
    println!("cargo:rerun-if-changed=src/{dir}");
    let src = manifest.join("src").join(dir);
    let mut files: Vec<PathBuf> = fs::read_dir(&src)
        .unwrap_or_else(|e| panic!("cannot list {}: {e}", src.display()))
        .map(|e| e.unwrap_or_else(|e| panic!("cannot list {}: {e}", src.display())).path())
        .filter(|p| p.extension().is_some_and(|x| x == "rs"))
        .collect();
    files.sort();
    let mut text = format!(
        "// @generated by kiln_diag's build.rs from src/{dir}/*.rs (spec/diag.md §2.4).\n\
         macro_rules! {table} {{\n    ($($tail:tt)*) => {{\n        {inner}! {{\n"
    );
    for f in &files {
        let rows =
            fs::read_to_string(f).unwrap_or_else(|e| panic!("cannot read {}: {e}", f.display()));
        let name = f.file_name().and_then(|n| n.to_str()).unwrap_or_default();
        text.push_str(&format!("            // src/{dir}/{name}\n"));
        for line in rows.lines().map(str::trim).filter(|l| !l.is_empty() && !l.starts_with("//")) {
            text.push_str("            ");
            text.push_str(line);
            text.push('\n');
        }
    }
    text.push_str("            $($tail)*\n        }\n    };\n}\n");
    let dest = out.join(format!("{table}.rs"));
    if fs::read_to_string(&dest).ok().as_deref() != Some(text.as_str()) {
        fs::write(&dest, text).unwrap_or_else(|e| panic!("cannot write {}: {e}", dest.display()));
    }
}
